BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Clearly trivial misstatement threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgemont Electronics, the auditor identifies a $200 error in office supplies expense. Overall materiality for the engagement is $500,000. Under AU-C 450, the auditor should classify this misstatement as:', '["A projected misstatement requiring further investigation", "A judgmental misstatement that should be communicated to management", "Clearly trivial and not required to be accumulated", "An immaterial factual misstatement that must still be documented on the summary"]'::jsonb, 2, 'Under AU-C 450.A2, misstatements are clearly trivial when they are inconsequential both individually and in the aggregate. A $200 error against $500,000 materiality is well below any reasonable threshold. Unlike choice D, clearly trivial amounts need not be accumulated at all because they could not reasonably affect users'' decisions regarding the financial statements.', 'medium', 2),

-- Q2: medium / L3 — Qualitative factors in misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'While evaluating uncorrected misstatements at Parkview Hospitality, the auditor discovers a $12,000 understatement of executive compensation disclosure. Quantitative materiality is $250,000. The auditor determines the misstatement is nonetheless significant because:', '["It exceeds the clearly trivial threshold established for the engagement", "Qualitative factors such as sensitivity of executive compensation disclosures can render quantitatively immaterial misstatements significant", "All disclosure misstatements are automatically considered material regardless of dollar amount", "The misstatement must be projected to the full population before its significance can be assessed"]'::jsonb, 1, 'Under AU-C 450.11, the auditor evaluates whether uncorrected misstatements are material individually or in aggregate, considering both size and qualitative factors. Executive compensation is a sensitive disclosure area where users may be influenced regardless of dollar amount. Unlike choice C, not all disclosure misstatements are automatically material — the auditor must apply professional judgment about the specific qualitative context.', 'medium', 3),

-- Q3: easy / L1 — Deficiency in design definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a deficiency in design exists when:', '["A necessary control is missing or not properly structured to prevent or detect misstatements on a timely basis", "An employee fails to perform an existing control procedure correctly", "The control operates effectively but is not documented in writing", "Management has not communicated the control policy to operating personnel"]'::jsonb, 0, 'Under AU-C 265.07, a deficiency in design exists when a control necessary to meet a control objective is missing, or when an existing control is not properly designed so that even if it operates as designed, it cannot prevent or detect misstatements timely. Unlike choice B, which describes a deficiency in operation, a design deficiency means the control itself is absent or flawed regardless of how it is performed.', 'easy', 1),

-- Q4: easy / L1 — Summary of uncorrected misstatements purpose
(1, 'Misstatements and Control Deficiencies', 'The primary purpose of the auditor''s summary of uncorrected misstatements is to:', '["Provide evidence that the audit was conducted in accordance with professional standards", "Document the basis for assessing penalties against management for noncompliance", "Serve as a basis for adjusting the financial statements after the audit report date", "Enable the auditor to evaluate whether uncorrected misstatements are material individually or in the aggregate"]'::jsonb, 3, 'Under AU-C 450.06, the auditor accumulates misstatements identified during the audit other than those that are clearly trivial. The summary allows evaluation of whether uncorrected misstatements are material, individually or in aggregate, to the financial statements as a whole. Unlike choice A, the summary''s primary purpose is evaluating aggregate misstatement impact, not evidencing compliance with auditing standards.', 'easy', 1),

-- Q5: medium / L2 — Prior-year restatement as MW indicator
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakeshore Enterprises, the auditor discovers that the company restated its prior-year financial statements due to an undetected revenue recognition error. Under AU-C 265, the restatement of previously issued financial statements is best characterized as:', '["An insignificant control deficiency requiring no further action", "A strong indicator of a material weakness in internal control", "A deficiency in auditing procedures rather than in the entity''s internal control", "A scope limitation requiring withdrawal from the engagement"]'::jsonb, 1, 'Under AU-C 265.A13, restatement of previously issued financial statements to correct a material misstatement is a strong indicator of a material weakness. The failure of controls to prevent or detect the original error demonstrates that a reasonable possibility of material misstatement existed. Unlike choice C, the deficiency resides in the entity''s controls, not the auditor''s procedures.', 'medium', 2),

-- Q6: medium / L2 — Timing of written communication
(1, 'Misstatements and Control Deficiencies', 'After completing fieldwork at Silverstone Manufacturing on March 15, 2026, the auditor issues the audit report on April 10, 2026. Under AU-C 265, the written communication of significant deficiencies and material weaknesses to those charged with governance must be made no later than:', '["60 days following the release of the auditor''s report", "30 days after the completion of fieldwork", "The date the audit report is issued", "90 days following the fiscal year-end"]'::jsonb, 0, 'Under AU-C 265.13, the auditor communicates significant deficiencies and material weaknesses in writing no later than 60 days following the release of the auditor''s report. This allows proper evaluation and classification of identified deficiencies. Unlike choice C, the written communication is not required to be issued simultaneously with the audit report, though timely communication is encouraged.', 'medium', 2),

-- Q7: hard / L4 — Pervasive uncorrected misstatements and opinion type
(1, 'Misstatements and Control Deficiencies', 'Meridian Global Corp. has uncorrected misstatements totaling $380,000 against overall materiality of $400,000. The misstatements span revenue, cost of goods sold, and inventory across multiple periods and affect key financial ratios used by lenders. After considering further possible misstatement from undetected errors, the auditor concludes the financial statements are materially misstated and the effects are pervasive. The most appropriate audit opinion is:', '["Unmodified opinion with an emphasis-of-matter paragraph", "Qualified opinion due to material but not pervasive misstatement", "Disclaimer of opinion due to inability to obtain sufficient evidence", "Adverse opinion because the misstatements are both material and pervasive"]'::jsonb, 3, 'Under AU-C 705.09, when uncorrected misstatements are both material and pervasive to the financial statements, an adverse opinion is required. Pervasiveness means the effects are not confined to specific elements but affect multiple accounts and periods. Unlike choice B, which applies when misstatements are material but confined to specific elements, an adverse opinion is warranted when the effects are widespread.', 'hard', 4),

-- Q8: hard / L3 — Roll-forward effects of prior-year uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Industries, the auditor notes that $45,000 in uncorrected overstatements of accrued liabilities from the prior year reversed in the current year, improving current-year net income. Under AU-C 450, when evaluating current-year misstatements the auditor should:', '["Ignore prior-year misstatements because they were evaluated in the prior-year audit", "Treat the reversal as a correcting entry that eliminates the need for further evaluation", "Consider the effect of prior-year uncorrected misstatements on the current-year financial statements", "Require management to restate the prior-year financial statements before completing the current audit"]'::jsonb, 2, 'Under AU-C 450.07, the auditor must consider the effect of uncorrected misstatements from prior periods on the current-year financial statements. The $45,000 reversal inflates current-year income, which must be evaluated in the aggregate assessment. Unlike choice A, prior-year uncorrected misstatements cannot simply be ignored because their reversal directly impacts current-year results.', 'hard', 3),

-- Q9: medium / L3 — Management representation letter on uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Beacon Financial Group, the auditor provides management with a summary of uncorrected misstatements totaling $35,000 against materiality of $200,000. Under AU-C 450, the auditor should request that management:', '["Provide a written representation that the effects of uncorrected misstatements are immaterial individually and in the aggregate to the financial statements as a whole", "Sign an acknowledgment that the auditor is not responsible for the uncorrected misstatements", "Include the summary of uncorrected misstatements as a note to the financial statements", "Adjust the financial statements for all misstatements regardless of materiality"]'::jsonb, 0, 'Under AU-C 450.14, the auditor requests a written representation from management that the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. This representation places responsibility on management for the decision not to correct. Unlike choice B, the purpose is management''s acknowledgment of immateriality, not a liability release for the auditor.', 'medium', 3),

-- Q10: medium / L2 — Prudent official test for control deficiency severity
(1, 'Misstatements and Control Deficiencies', 'When evaluating the severity of an identified control deficiency at Trident Logistics, the auditor applies the "prudent official" test described in AU-C 265. Under this framework, a significant deficiency is one that:', '["Has already resulted in a material misstatement in the current period", "A reasonable person relying on the financial statements would consider important enough to merit the attention of those charged with governance", "Requires immediate corrective action by management within 30 days of notification", "Can only be identified through substantive testing rather than tests of controls"]'::jsonb, 1, 'Under AU-C 265.A4, a significant deficiency is evaluated using the prudent official concept — whether a reasonable person relying on the financial statements would consider the deficiency important enough to merit governance attention. Unlike choice A, a significant deficiency does not require an actual misstatement to have occurred; the potential for misstatement is sufficient for classification.', 'medium', 2),

-- Q11: easy / L1 — Clearly trivial definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, a misstatement is considered "clearly trivial" when it is:', '["Below the performance materiality threshold but above the posting threshold", "Less than 5% of overall materiality as required by auditing standards", "Inconsequential whether judged individually or in the aggregate and whether judged by size, nature, or circumstances", "Any amount that management deems immaterial to the financial statements"]'::jsonb, 2, 'Under AU-C 450.A2, clearly trivial is not another expression for "not material." Misstatements are clearly trivial when they are inconsequential by any measure — size, nature, or circumstances — individually and in aggregate. Unlike choice B, auditing standards do not prescribe a specific percentage threshold; the auditor exercises professional judgment to determine what is clearly trivial.', 'easy', 1),

-- Q12: hard / L4 — Netting misstatements across accounts
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cornerstone Retail, the auditor identifies a $60,000 overstatement in sales revenue and a $55,000 understatement in cost of goods sold. Management argues the net effect of $5,000 on net income is immaterial and both should be treated as a single offsetting misstatement. Materiality is $100,000. The auditor should:', '["Accept management''s position because the net effect on net income is clearly immaterial", "Agree that offsetting misstatements within the income statement may be netted for evaluation purposes", "Combine the misstatements algebraically and evaluate only the net $5,000 impact on net income", "Evaluate each misstatement separately because they affect different financial statement line items and user decisions"]'::jsonb, 3, 'Under AU-C 450.11, the auditor evaluates misstatements considering their effect on individual line items, subtotals, and the financial statements as a whole. Revenue and COGS are separately important to users analyzing margins and trends. Unlike choice C, netting misstatements across different line items can obscure individually significant distortions that affect ratio analysis, trend comparisons, and other user decisions.', 'hard', 4),

-- Q13: easy / L1 — Communication of other deficiencies below significant
(1, 'Misstatements and Control Deficiencies', 'When the auditor identifies control deficiencies that are not significant deficiencies or material weaknesses, the auditor:', '["Is prohibited from communicating these deficiencies to anyone", "May communicate these other deficiencies to management in writing or orally", "Must include these deficiencies in the same written communication as significant deficiencies", "Is required to report all deficiencies to the SEC regardless of severity"]'::jsonb, 1, 'Under AU-C 265.A18, the auditor may communicate control deficiencies that are not significant deficiencies or material weaknesses to management, either in writing or orally. This communication is optional, not mandatory. Unlike choice A, auditing standards do not prohibit communicating lesser deficiencies — they simply do not require it in the formal written communication to governance.', 'easy', 1),

-- Q14: easy / L1 — Deficiency in operation definition
(1, 'Misstatements and Control Deficiencies', 'A deficiency in operation under AU-C 265 occurs when:', '["A properly designed control does not operate effectively or is not performed by a person with the necessary authority or competence", "No control exists to address a particular financial reporting objective", "The control was designed for a different process than the one it is applied to", "Management decides not to implement a recommended control improvement"]'::jsonb, 0, 'Under AU-C 265.07, a deficiency in operation exists when a properly designed control does not operate effectively, meaning the person performing the control lacks the necessary authority or competence, or the control is not performed consistently. Unlike choice B, the absence of a control entirely is a design deficiency, not an operating deficiency. The distinction is critical for remediation efforts.', 'easy', 1),

-- Q15: medium / L3 — Misstatements arising from fraud vs. error
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northwind Distributors, the auditor discovers that a purchasing manager created fictitious vendor invoices totaling $42,000 to embezzle funds. The scheme was not prevented by segregation-of-duties controls. Under AU-C 240 and AU-C 265, the auditor should evaluate this finding by:', '["Treating the misstatement identically to an unintentional error of the same dollar amount", "Limiting evaluation to the quantitative impact of the $42,000 on the financial statements", "Recognizing that misstatements from fraud have broader implications for control deficiency severity and may indicate a material weakness even at amounts below quantitative materiality", "Communicating the fraud only to law enforcement without including it in the control deficiency evaluation"]'::jsonb, 2, 'Under AU-C 240.35 and AU-C 265.A12, fraud-related misstatements carry qualitative significance beyond their dollar amount. A fraud that circumvented segregation of duties suggests systemic control failures, elevating deficiency severity regardless of the quantitative threshold. Unlike choice A, auditing standards require the auditor to consider the nature and cause of misstatements, not just their magnitude, when evaluating implications.', 'medium', 3),

-- Q16: medium / L3 — Documentation requirements for misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Pacific Coast Logistics, the auditor documents the evaluation of uncorrected misstatements. Under AU-C 450.15, the auditor''s documentation must include:', '["Only the total dollar amount of uncorrected misstatements and a brief narrative", "A summary of misstatements identified above the clearly trivial threshold but only those exceeding performance materiality", "The list of corrected misstatements and the names of management personnel responsible for each error", "The amount below which misstatements are regarded as clearly trivial, all misstatements accumulated during the audit, and the auditor''s conclusion on whether uncorrected misstatements are material"]'::jsonb, 3, 'Under AU-C 450.15, documentation must include the clearly trivial threshold, all accumulated misstatements and whether they were corrected, and the auditor''s conclusion about whether uncorrected misstatements are material individually or in aggregate. Unlike choice A, a bare total is insufficient — the auditor must document the threshold, individual items, and the overall materiality conclusion.', 'medium', 3),

-- Q17: medium / L2 — Control environment deficiency as MW indicator
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Capital Advisors, the auditor discovers that the CEO routinely overrides established approval controls to process transactions without review. Under AU-C 265, management override of controls is significant because it:', '["Is a strong indicator of a material weakness because it undermines the overall control environment", "Is expected in small organizations and generally does not affect deficiency classification", "Only rises to a significant deficiency if the overrides result in misstatements exceeding materiality", "Must be reported directly to regulatory authorities before evaluating as a control deficiency"]'::jsonb, 0, 'Under AU-C 265.A13, ineffective oversight by those charged with governance, including management override of controls, is identified as a strong indicator of a material weakness. Override undermines the entire control environment, which is the foundation of internal control. Unlike choice B, management override is a serious concern regardless of entity size and warrants careful evaluation of deficiency severity.', 'medium', 2),

-- Q18: medium / L2 — Recurring nature of misstatements
(1, 'Misstatements and Control Deficiencies', 'During three consecutive annual audits of Granite Peak Mining, the auditor has identified similar misstatements in the depreciation calculation for mining equipment. Management has not corrected these errors in any year. The recurring nature of these misstatements is most relevant to the auditor''s evaluation because it:', '["Automatically converts an insignificant deficiency into a material weakness after three occurrences", "Has no bearing on deficiency evaluation since each year is audited independently", "Suggests a systemic control deficiency that increases the likelihood of material misstatement and may elevate the severity classification", "Requires the auditor to withdraw from the engagement after repeated refusal to correct"]'::jsonb, 2, 'Under AU-C 265.A11, the auditor considers whether deficiencies have been communicated previously without being remediated. Recurring misstatements indicate systemic rather than isolated control failures, increasing the likelihood and potential magnitude of future misstatements. Unlike choice A, there is no automatic threshold based on the number of occurrences — the auditor must evaluate severity using professional judgment.', 'medium', 2),

-- Q19: easy / L2 — Magnitude vs. likelihood in deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'When evaluating the severity of a control deficiency at Brookfield Consulting, the auditor considers two primary factors. Under AU-C 265, these factors are:', '["The cost to remediate the deficiency and the time required to implement corrective action", "The magnitude of the potential misstatement and the likelihood that the deficiency could result in a misstatement", "The number of transactions affected and the total revenue of the entity", "The experience level of accounting personnel and the complexity of the entity''s operations"]'::jsonb, 1, 'Under AU-C 265.A8, the severity of a control deficiency depends on the magnitude of the potential misstatement resulting from the deficiency and the likelihood that the deficiency could result in a material misstatement. Unlike choice A, remediation cost and implementation time are operational considerations for management, not factors in the auditor''s severity assessment under auditing standards.', 'easy', 2),

-- Q20: easy / L1 — Tolerable misstatement in sampling
(1, 'Misstatements and Control Deficiencies', 'In the context of audit sampling, tolerable misstatement is best defined as:', '["The maximum misstatement in a population that the auditor is willing to accept and still conclude the audit objective has been achieved", "The total amount of known misstatements identified through substantive testing", "A misstatement that management has agreed is acceptable and will not correct", "The dollar amount above which all misstatements must be reported to governance"]'::jsonb, 0, 'Under AU-C 530.A3, tolerable misstatement is the application of performance materiality to a particular sampling procedure. It represents the maximum misstatement the auditor can accept in a population while still concluding the account is not materially misstated. Unlike choice C, tolerable misstatement is an auditor-determined threshold for sampling, not an agreement with management about acceptable errors.', 'easy', 1),

-- Q21: hard / L4 — Disaggregation of misstatements by line item
(1, 'Misstatements and Control Deficiencies', 'Atlas Manufacturing has uncorrected misstatements totaling $90,000, which is below overall materiality of $150,000. However, $75,000 of the total relates to accounts receivable, where the specific account-level materiality is $80,000. The remaining $15,000 is spread across five other accounts. When forming the audit opinion, the auditor should:', '["Conclude the financial statements are fairly presented because total misstatements are below overall materiality", "Issue a qualified opinion on accounts receivable only while giving an unqualified opinion on other accounts", "Disclose the misstatements in an emphasis-of-matter paragraph but issue an unmodified opinion", "Consider whether the concentration of misstatements in accounts receivable, at 94% of its specific materiality, could cause the account or related financial statement subtotals to be materially misstated"]'::jsonb, 3, 'Under AU-C 450.11, the auditor evaluates misstatements in relation to particular classes of transactions, account balances, and disclosures — not solely against overall materiality. A $75,000 misstatement approaching the $80,000 account-level threshold requires specific evaluation. Unlike choice A, aggregate immateriality at the financial-statement level does not automatically mean individual accounts are fairly stated.', 'hard', 4),

-- Q22: easy / L1 — Scope limitation versus misstatement distinction
(1, 'Misstatements and Control Deficiencies', 'The key distinction between a misstatement and a scope limitation is that:', '["A misstatement has no effect on the audit opinion while a scope limitation always does", "A misstatement involves a known or estimated error in the financial statements while a scope limitation involves the inability to obtain sufficient appropriate audit evidence", "Misstatements can only be quantitative while scope limitations can only be qualitative", "Scope limitations are caused by management while misstatements are caused by the auditor"]'::jsonb, 1, 'Under AU-C 705, a misstatement is a difference between the amount, classification, or disclosure of a reported item and what is required by the applicable framework. A scope limitation is a restriction on obtaining evidence needed to conclude on an assertion. Unlike choice A, both misstatements and scope limitations can lead to modified opinions depending on their materiality and pervasiveness.', 'easy', 1),

-- Q23: medium / L3 — Interim communication of control deficiencies
(1, 'Misstatements and Control Deficiencies', 'During interim fieldwork at Redwood Financial Services in September 2025, the auditor identifies what appears to be a material weakness in the loan approval process. The fiscal year ends December 31, 2025. Under AU-C 265, the auditor should:', '["Communicate the material weakness to those charged with governance on a timely basis rather than waiting until the audit is complete, because of its significance", "Wait until year-end fieldwork is complete to ensure the classification is accurate before any communication", "Communicate the deficiency only to management because the audit is not yet finished", "Defer communication until the formal 60-day deadline after the audit report is released"]'::jsonb, 0, 'Under AU-C 265.12, the auditor should communicate significant deficiencies and material weaknesses on a timely basis. When a material weakness is identified during interim work, delaying communication would deprive governance of the opportunity to take corrective action. Unlike choice B, the significance of a material weakness warrants prompt communication even if the final classification might be refined during year-end procedures.', 'medium', 3),

-- Q24: medium / L3 — Preventive vs. detective control failures
(1, 'Misstatements and Control Deficiencies', 'At Pinnacle Energy Corp., the auditor discovers that a preventive control over journal entry approval was bypassed, but a detective control — the monthly account reconciliation — identified and corrected the resulting misstatement before period close. When evaluating the overall control deficiency, the auditor should consider that:', '["The failure of the preventive control is irrelevant because the detective control ultimately worked as intended", "Only the detective control''s effectiveness matters when determining the deficiency classification", "The preventive control failure remains a deficiency, and the auditor should evaluate whether the compensating detective control sufficiently reduces the risk of material misstatement", "The presence of both a preventive and detective control means no reportable deficiency exists"]'::jsonb, 2, 'Under AU-C 265.A10, the auditor considers compensating controls when evaluating severity. While the detective control mitigated the actual misstatement, the preventive control failure remains a deficiency because it allowed the error to occur. Unlike choice A, the existence of a compensating detective control reduces but does not eliminate the deficiency — the auditor must assess whether the compensating control sufficiently addresses the risk.', 'medium', 3),

-- Q25: hard / L4 — Misstatement evaluation in group audits
(1, 'Misstatements and Control Deficiencies', 'Nova International Group has three subsidiaries audited by component auditors. Component A reports uncorrected misstatements of $30,000, Component B reports $25,000, and Component C reports $20,000. Group materiality is $100,000, and component materiality was set at $40,000 each. The group auditor should:', '["Accept each component''s conclusion that misstatements are immaterial since all are below component materiality", "Aggregate the uncorrected misstatements from all components ($75,000) and evaluate against group materiality, considering the nature and cause of each component''s misstatements", "Evaluate only the largest component misstatement against group materiality", "Require each component auditor to lower materiality and perform additional procedures"]'::jsonb, 1, 'Under AU-C 600.44 and AU-C 450, the group auditor must aggregate uncorrected misstatements from all components and evaluate them against group materiality. The combined $75,000 approaches group materiality of $100,000 and warrants careful assessment. Unlike choice A, the fact that individual component misstatements are below component materiality does not preclude their aggregate from being material at the group level.', 'hard', 4),

-- Q26: easy / L1 — Compensating controls and MW classification
(1, 'Misstatements and Control Deficiencies', 'When evaluating whether a control deficiency is a material weakness, the presence of compensating controls is relevant because:', '["Compensating controls automatically eliminate any identified deficiency from the report", "The auditor is prohibited from considering compensating controls in the severity assessment", "Compensating controls are only relevant for public company audits under PCAOB standards", "Effective compensating controls may reduce the likelihood or magnitude of potential misstatement, thereby affecting the deficiency''s severity classification"]'::jsonb, 3, 'Under AU-C 265.A10, the auditor considers whether compensating controls sufficiently address the risk posed by the identified deficiency. Effective compensating controls can reduce the severity classification by lowering the likelihood or magnitude of a potential misstatement. Unlike choice A, compensating controls do not automatically eliminate a deficiency; they may only reduce its severity from material weakness to significant deficiency or lower.', 'easy', 1),

-- Q27: medium / L2 — IT general control deficiencies and financial reporting
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Technologies, the auditor discovers that the company has no formal change management process for its financial reporting application. Programmers can modify production code without approval or testing. Under AU-C 265, the auditor should evaluate this IT deficiency by:', '["Assessing whether the absence of change management controls could result in unauthorized or untested changes that lead to financial statement misstatements, thereby determining the deficiency''s severity", "Ignoring the IT deficiency because AU-C 265 applies only to manual controls", "Classifying all IT deficiencies as significant deficiencies by default", "Reporting the finding to the entity''s IT department without including it in the control deficiency evaluation"]'::jsonb, 0, 'Under AU-C 265.A6, IT general controls, including change management, are evaluated for their potential impact on financial reporting. Unauthorized program changes can compromise the integrity of automated controls and financial data. Unlike choice B, AU-C 265 encompasses all controls relevant to the audit, including IT controls, and the auditor must assess their impact on the likelihood and magnitude of potential misstatements.', 'medium', 2),

-- Q28: hard / L4 — Subsequent discovery of misstatement after report release
(1, 'Misstatements and Control Deficiencies', 'Three months after issuing an unmodified audit opinion on Harborview Medical Center, the auditor discovers that a $500,000 revenue misstatement existed at the balance sheet date. The misstatement exceeds materiality. Management refuses to revise the financial statements. Under AU-C 560, the auditor''s most appropriate course of action is to:', '["Take no action because the auditor''s responsibility ended upon report issuance", "Re-issue the audit report with an unmodified opinion and a subsequent events paragraph", "Notify those charged with governance of management''s refusal and consider what further action is appropriate, including notifying regulatory authorities and persons known to be relying on the financial statements", "Withdraw the audit report and terminate the engagement without further communication"]'::jsonb, 2, 'Under AU-C 560.17-.18, when management refuses to revise financial statements containing a subsequently discovered material misstatement, the auditor should notify governance and consider appropriate further steps, including informing parties relying on the statements. Unlike choice A, the auditor''s responsibility does not end at report issuance — AU-C 560 imposes obligations when facts become known after the report date that would have affected the opinion.', 'hard', 3),

-- Q29: medium / L3 — Misstatements affecting compliance with debt covenants
(1, 'Misstatements and Control Deficiencies', 'During the audit of Eastgate Properties, the auditor identifies an uncorrected $18,000 understatement of interest expense. While immaterial quantitatively against $300,000 materiality, correcting this misstatement would cause the company to violate its debt-to-equity covenant with its primary lender. When evaluating this misstatement, the auditor should:', '["Disregard the covenant implications because the misstatement is quantitatively immaterial", "Consider the covenant violation as a qualitative factor that may render the misstatement material despite its small dollar amount", "Require management to renegotiate the covenant before the audit can be completed", "Report the misstatement to the lender directly without further evaluation"]'::jsonb, 1, 'Under AU-C 450.A5, the auditor considers qualitative factors including whether a misstatement affects compliance with debt covenants or other contractual requirements. A misstatement that triggers a covenant violation has significant economic consequences beyond its dollar amount. Unlike choice A, the auditor cannot disregard covenant implications simply because the misstatement falls below quantitative materiality — qualitative considerations may override quantitative assessments.', 'medium', 3),

-- Q30: medium / L2 — Prior-year MW and current-year auditor responsibilities
(1, 'Misstatements and Control Deficiencies', 'The predecessor auditor of Crestline Industries communicated a material weakness in the revenue recognition process in the prior-year audit. During the current-year audit, the successor auditor should:', '["Assume the material weakness has been corrected if management asserts that remediation occurred", "Rely solely on the predecessor auditor''s workpapers to evaluate the current status of the deficiency", "Accept management''s classification of the deficiency without independent assessment", "Evaluate whether the material weakness continues to exist by performing current-year procedures to test the relevant controls and assess their operating effectiveness"]'::jsonb, 3, 'Under AU-C 265.A15, the auditor considers whether previously communicated deficiencies remain unremediated. The current-year auditor must independently evaluate the control environment rather than relying on management assertions or predecessor conclusions alone. Unlike choice A, management''s claim of remediation requires verification through testing of the redesigned or newly implemented controls to confirm effective operation.', 'medium', 2)
;

COMMIT;
